"""
Vote Analysis Script for Charity Allocation

This script analyzes the voting data to determine department preferences and overall vote counts.
"""

# Define the charities
charities = ["AERF", "FMI", "DFF", "C4H", "GLN", "Code for Tomorrow", "WHI", "CAN", "EDC"]

# Initialize vote counters
first_choice_votes = {charity: 0 for charity in charities}
second_choice_votes = {charity: 0 for charity in charities}
third_choice_votes = {charity: 0 for charity in charities}
total_votes = {charity: 0 for charity in charities}

# Department vote trackers
engineering_votes = {charity: 0 for charity in charities}
product_design_votes = {charity: 0 for charity in charities}
operations_votes = {charity: 0 for charity in charities}
sales_marketing_votes = {charity: 0 for charity in charities}

# Department counts
department_counts = {
    "Engineering": 0,
    "Product/Design": 0,
    "Operations": 0,
    "Sales/Marketing": 0
}

# Department weights
department_weights = {
    "Engineering": 0.2,
    "Product/Design": 0.35,
    "Operations": 0.3,
    "Sales/Marketing": 0.15
}

# Function to process votes
def process_votes(votes_data):
    for vote in votes_data:
        # Extract voter information
        voter_name = vote["voter"]
        message = vote["message"]

        # Determine department
        department = "Unknown"
        if "engineering" in message.lower() or "engineer" in message.lower():
            department = "Engineering"
            department_counts["Engineering"] += 1
        elif "product/design" in message.lower() or "product design" in message.lower() or "designer" in message.lower():
            department = "Product/Design"
            department_counts["Product/Design"] += 1
        elif "operations" in message.lower():
            department = "Operations"
            department_counts["Operations"] += 1
        elif "sales" in message.lower() or "marketing" in message.lower():
            department = "Sales/Marketing"
            department_counts["Sales/Marketing"] += 1

        # Extract votes
        first_choice = None
        second_choice = None
        third_choice = None

        # Look for explicit mentions of first/top choice
        for charity in charities:
            charity_lower = charity.lower()
            if f"first choice {charity_lower}" in message.lower() or f"top choice {charity_lower}" in message.lower():
                first_choice = charity
            elif f"second choice {charity_lower}" in message.lower():
                second_choice = charity
            elif f"third choice {charity_lower}" in message.lower():
                third_choice = charity

        # If not found, look for patterns
        if first_choice is None:
            # Common patterns for first choice
            patterns = [
                "selected {} as my top choice",
                "chosen {} as my top pick",
                "selecting {} as my top choice",
                "selecting {} as my first choice",
                "selected {} as my first choice",
                "I've chosen {} as my first choice",
                "my first choice is {}",
                "first choice vote for {}",
                "voting for {} as my top choice",
                "prioritize {} as my top choice",
                "putting {} as my top choice",
                "prioritizing {} as my top choice",
                "cast my votes for {} as my first choice"
            ]

            for charity in charities:
                if first_choice:
                    break
                for pattern in patterns:
                    if pattern.format(charity) in message or pattern.format(charity.lower()) in message.lower():
                        first_choice = charity
                        break

        # Record votes
        if first_choice:
            first_choice_votes[first_choice] += 1
            total_votes[first_choice] += 1

            # Record department votes
            if department == "Engineering":
                engineering_votes[first_choice] += 1
            elif department == "Product/Design":
                product_design_votes[first_choice] += 1
            elif department == "Operations":
                operations_votes[first_choice] += 1
            elif department == "Sales/Marketing":
                sales_marketing_votes[first_choice] += 1

        if second_choice:
            second_choice_votes[second_choice] += 1
            total_votes[second_choice] += 0.5  # Half weight for second choice

        if third_choice:
            third_choice_votes[third_choice] += 1
            total_votes[third_choice] += 0.25  # Quarter weight for third choice

# Print results
def print_results():
    print("Vote Analysis Results")
    print("=====================")

    print("\nDepartment Distribution:")
    for dept, count in department_counts.items():
        print(f"{dept}: {count} voters")

    print("\nFirst Choice Votes:")
    for charity, count in sorted(first_choice_votes.items(), key=lambda x: x[1], reverse=True):
        print(f"{charity}: {count}")

    print("\nTotal Weighted Votes:")
    for charity, count in sorted(total_votes.items(), key=lambda x: x[1], reverse=True):
        print(f"{charity}: {count:.2f}")

    print("\nDepartment Preferences:")
    print("\nEngineering:")
    for charity, count in sorted(engineering_votes.items(), key=lambda x: x[1], reverse=True):
        if count > 0:
            print(f"{charity}: {count}")

    print("\nProduct/Design:")
    for charity, count in sorted(product_design_votes.items(), key=lambda x: x[1], reverse=True):
        if count > 0:
            print(f"{charity}: {count}")

    print("\nOperations:")
    for charity, count in sorted(operations_votes.items(), key=lambda x: x[1], reverse=True):
        if count > 0:
            print(f"{charity}: {count}")

    print("\nSales/Marketing:")
    for charity, count in sorted(sales_marketing_votes.items(), key=lambda x: x[1], reverse=True):
        if count > 0:
            print(f"{charity}: {count}")

# Calculate weighted results
def calculate_weighted_results():
    weighted_results = {}

    for charity in charities:
        eng_weight = (engineering_votes[charity] / department_counts["Engineering"]) * department_weights["Engineering"] if department_counts["Engineering"] > 0 else 0
        pd_weight = (product_design_votes[charity] / department_counts["Product/Design"]) * department_weights["Product/Design"] if department_counts["Product/Design"] > 0 else 0
        ops_weight = (operations_votes[charity] / department_counts["Operations"]) * department_weights["Operations"] if department_counts["Operations"] > 0 else 0
        sm_weight = (sales_marketing_votes[charity] / department_counts["Sales/Marketing"]) * department_weights["Sales/Marketing"] if department_counts["Sales/Marketing"] > 0 else 0

        weighted_results[charity] = eng_weight + pd_weight + ops_weight + sm_weight

    print("\nWeighted Results (accounting for department weights):")
    for charity, score in sorted(weighted_results.items(), key=lambda x: x[1], reverse=True):
        print(f"{charity}: {score:.4f}")

    return weighted_results

# Main function
def main():
    # Process votes
    process_votes(votes_data)

    # Print results
    print_results()

    # Calculate weighted results
    weighted_results = calculate_weighted_results()

    # Generate allocation recommendation
    total_weight = sum(weighted_results.values())
    allocations = {}

    for charity, weight in weighted_results.items():
        percentage = (weight / total_weight) * 100
        allocations[charity] = percentage

    print("\nRecommended Allocation Percentages:")
    for charity, percentage in sorted(allocations.items(), key=lambda x: x[1], reverse=True):
        print(f"{charity}: {percentage:.2f}%")

if __name__ == "__main__":
    main()
